    private static void TenantFilter<T>(ModelBuilder model, TenantContext tenant) where T : TenantEntity => model.Entity<T>().HasQueryFilter(x => tenant.IsPlatformContext || tenant.TenantId != null && x.TenantId == tenant.TenantId);
